//! ♻️ Original authority native storage remains fixed until each admitted child and ledger is empty.
use super::*;
use super::testing::{Fixture,STOCK};
#[repr(transparent)]
struct TerminalJob<const N:usize>([u8;N]);
impl<const N:usize> InteractiveJob for TerminalJob<N>{fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,OriginalTurnFailure>{JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from)}fn borrow_outcome<'a>(&'a self,d:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{d.yielded()}fn begin_close(&mut self){}fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}fn terminal_is_empty(&self)->bool{true}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn params()->BatchJobParams{BatchJobParams{operation:OperationId(98120),generation:Generation(12),cancel:root_cancel_token(),config:BatchDriveConfig{retained:STOCK,site:"native-authority-retirement",stage:InteractiveStage::InteractiveStep,fuel_per_step:10000,step_budget_us:1000000},now_us:default_now_us}}
fn close_once<const N:usize>(fixture:&mut Fixture<TerminalJob<N>>,grant:RetainedCloneGrant)->(WorkerJobCloseStep,(usize,usize)){observe(||fixture.caller.turn(grant,|cx|{if fixture.owner.has_original_cancel_alias_witness(cx.original_cancel_token()){let step=fixture.owner.return_original_cancel_alias_step(cx.original_cancel_token(),cx.retained_grant()).map_err(|error|match error{semio_framework_async::CancelTokenRetirementError::Refused(error)=>OriginalTurnFailure::from(error),semio_framework_async::CancelTokenRetirementError::Blocked(_)=>OriginalTurnFailure::from(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native authority alias remains blocked"))})?.unwrap();cx.consume_retained(step.progress())?;cx.consume_fuel(1);Ok(WorkerJobCloseStep::Pending{progress:step.progress()})}else{fixture.owner.close_step(cx)}}).unwrap())}
fn authority_law<const N:usize>(){let mut fixture=Fixture::admit(TerminalJob([7;N]),params());let pointer=fixture.owner.original.0.as_ptr();let capacity=fixture.owner.original.0.capacity();let mut ledger_seen=false;let mut backing_seen=false;for _ in 0..512{if fixture.owner.terminal_is_empty(){break}let demand=fixture.owner.retirement_demands(4096).unwrap();let terminal_children=fixture.owner.original.child_custody_is_empty()||fixture.owner.close_phase()==OriginalWorkerAuthorityPhase::Ledger;if terminal_children{let ledger=fixture.owner.original.payload.ledger_is_present();if ledger{ledger_seen=true;assert_eq!(demand.release_bytes,OriginalWorkerPayload::ledger_release_bytes());}else{backing_seen=true;assert_eq!(demand.release_bytes,capacity*size_of::<NativeWorkerAuthorityState<TerminalJob<N>>>());}for denied in [Some(RetainedCloneGrant{maximum_items:0,..STOCK}),Some(RetainedCloneGrant{maximum_depth:0,..STOCK}),(demand.release_bytes>0&&!fixture.owner.has_original_cancel_alias_witness(fixture.caller.cancel())).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..STOCK})].into_iter().flatten(){let(step,heap)=close_once(&mut fixture,denied);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}}let(step,heap)=close_once(&mut fixture,STOCK);assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);if !fixture.owner.terminal_is_empty(){assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}}assert!(ledger_seen&&backing_seen);assert!(fixture.owner.terminal_is_empty());fixture.close();}
#[test]
fn worker_terminal_authority_retirement_preserves_original_ledger_then_in_place_backing(){authority_law::<0>();authority_law::<8192>();}
fn job_slot_law<const N:usize>(){let mut slot=WorkerJobSource::from_job(TerminalJob([7;N]),OperationId(99110),Generation(12));let pointer=slot.original().unwrap()as*const _;assert_eq!(slot.terminal_removal_demands().copy_bytes,0);for denied in [RetainedCloneGrant{maximum_items:0,..STOCK},RetainedCloneGrant{maximum_depth:0,..STOCK}]{let(step,heap)=observe(||slot.remove_terminal(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.original().unwrap()as*const _,pointer);}let(step,heap)=observe(||slot.remove_terminal(STOCK).unwrap());assert_eq!(heap,(0,0));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(slot.is_empty());assert_eq!(observe(||drop(slot)).1,(0,0));}
#[test]
fn worker_terminal_job_retirement_keeps_original_inline_job_for_in_place_removal(){job_slot_law::<0>();job_slot_law::<8192>();}
#[test]
fn worker_terminal_params_retirement_preserves_original_cancellation_and_separate_cursor(){for ancestors in [1,3,64]{let mut fixture=Fixture::admit(TerminalJob([]),params());for _ in 1..ancestors{fixture.caller.turn(STOCK,|cx|{let original=fixture.owner.original.params.as_mut().unwrap();let(child,receipt)=original.cancel.admit_child(cx.retained_grant())?.unwrap();cx.consume_retained(receipt)?;cx.consume_fuel(1);let old=std::mem::replace(&mut original.cancel,child);let((),heap)=observe(||drop(old));assert_eq!(heap,(0,0));cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);Ok(())}).unwrap();}let pointer=fixture.owner.original.0.as_ptr();for _ in 0..1024{if fixture.owner.terminal_is_empty(){break}let demand=fixture.owner.retirement_demands(4096).unwrap();for denied in [Some(RetainedCloneGrant{maximum_items:0,..STOCK}),(demand.release_bytes>0&&!fixture.owner.has_original_cancel_alias_witness(fixture.caller.cancel())).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..STOCK})].into_iter().flatten(){let(step,heap)=close_once(&mut fixture,denied);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}let(step,heap)=close_once(&mut fixture,STOCK);assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);if !fixture.owner.terminal_is_empty(){assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}}assert!(fixture.owner.terminal_is_empty());fixture.close();}}

struct RefusingSourceInitializer{written:bool}
unsafe impl WorkerJobInitializer<u8> for RefusingSourceInitializer{
 fn initialization_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:size_of::<u8>(),depth:1,..Default::default()})}
 unsafe fn initialize_step(&mut self,target:*mut MaybeUninit<u8>,_:RetainedCloneGrant)->Result<WorkerJobInitializationStep,ValueError>{unsafe{target.write(MaybeUninit::new(71));}self.written=true;Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original source writer refused after actual initialized byte and cursor").with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<u8>(),..Default::default()}))}
 fn initialization_input_is_empty(&self)->bool{true}
 fn partial_retirement_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
 unsafe fn close_partial_step(&mut self,_:*mut MaybeUninit<u8>,_:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Ok(RetainedCloneStep::Complete(Default::default()))}
 fn partial_terminal_is_empty(&self)->bool{true}

}
#[test]
fn original_source_preparation_keeps_failed_effects_in_same_incoming_recipient(){
 fn now()->Option<u64>{Some(1)}
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🚪️admission/🚚️staged/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let identity=(OperationId(99912),Generation(3));let mut storage=MaybeUninit::<WorkerJobSource<u8>>::uninit();let mut header=Default::default();let mut control=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,grant),now,&mut header).unwrap();let(source,birth)=WorkerJobSource::start_preparation(&mut storage,&mut control).unwrap().unwrap();drop(control);assert_eq!(birth,header);assert_eq!(birth.copied_bytes,law["sourceHeader"]["copiedBytes"].as_u64().unwrap()as usize);let mut writer=RefusingSourceInitializer{written:false};let mut recipient=Default::default();
 let mut control=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,RetainedCloneGrant{maximum_copy_bytes:0,..grant}),now,&mut recipient).unwrap();let(step,heap)=observe(||source.prepare_step(&mut writer,&mut control).unwrap());drop(control);assert_eq!(heap,(0,0));assert_eq!(step.progress,Default::default());assert_eq!(recipient,Default::default());assert!(!writer.written);assert!(source.source().is_none());
 let mut control=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(1,2,grant),now,&mut recipient).unwrap();let(error,heap)=observe(||source.prepare_step(&mut writer,&mut control).err().unwrap());drop(control);assert_eq!(heap,(0,0));assert!(writer.written);assert!(source.source().is_none());assert_eq!(unsafe{source.original.assume_init()},71);assert_eq!(error.retained_progress(),RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()});assert_eq!(recipient,error.retained_progress());assert!(recipient.fits(grant));
}

